'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const n = Number(input[0]);
const commands = input[1];

let x = 0;
let y = 0;
let answer = 0;

const frequencies = new Map();
frequencies.set('0,0', 1);

for (let i = 0; i < n; i++) {
    switch (commands[i]) {
        case 'U': y++; break;
        case 'D': y--; break;
        case 'R': x++; break;
        case 'L': x--; break;
    }

    const key = `${x},${y}`;
    const count = frequencies.get(key) || 0;
    answer += count;
    frequencies.set(key, count + 1);
}

console.log(answer);

